B.a_9=new A.hq("\ub0b4 \uacc4\uc57d\uc5d0\uc11c \uac00\ub2a5\ud55c \uc120\ud0dd\ubd80\ud130 \ud655\uc778\ud574\uc694","\ub9cc\uae30\uc5d0 \uc778\uc218\xb7\ubc18\ub0a9\xb7\uc5f0\uc7a5 \uc911 \ubb34\uc5c7\uc774 \uac00\ub2a5\ud55c\uc9c0\ub294 \uc0c1\ud488\uacfc \uacc4\uc57d\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc694. \ucc98\uc74c \uacc4\uc57d\ud560 \ub54c \uc815\ud55c \uc778\uc218 \uc870\uac74\uacfc \ub9cc\uae30 \uc548\ub0b4\ub97c \uba3c\uc800 \ud655\uc778\ud558\uc138\uc694.","\uacc4\uc57d\uc774 \ub05d\ub098\uac00\ub124. \uacc4\uc18d \ud0c8\uae4c, \ub3cc\ub824\uc904\uae4c?","\uc778\uc218\xb7\ubc18\ub0a9\xb7\uc5f0\uc7a5 \uac00\ub2a5 \uc5ec\ubd80\ub294 \ub0b4 \uacc4\uc57d\ubd80\ud130 \ud655\uc778\ud574\uc694.")
B.a_g=new A.hq("\ubc18\ub0a9\uc740 \ucc28 \uc0c1\ud0dc\uc640 \uc8fc\ud589\uac70\ub9ac\ub97c \ud655\uc778\ud574\uc694","\ucc28\ub97c \ub3cc\ub824\uc8fc\uba74 \ub418\uc9c0\ub9cc, \uc5b8\uc81c\ub098 \ucd94\uac00 \ube44\uc6a9 \uc5c6\uc774 \ub05d\ub098\ub294 \uac83\uc740 \uc544\ub2c8\uc5d0\uc694. \uc57d\uc815 \uc8fc\ud589\uac70\ub9ac \ucd08\uacfc, \ucc28\ub7c9 \uc190\uc0c1 \ub4f1 \uacc4\uc57d\uc0c1 \uc815\uc0b0 \ud56d\ubaa9\uacfc \ubc18\ub0a9 \uc7a5\uc18c\xb7\uc77c\uc815\uc744 \ud655\uc778\ud558\uc138\uc694.","\ubc18\ub0a9 \uc804\uc5d0 \uc8fc\ud589\uac70\ub9ac\uc640 \ucc28\ub7c9 \uc0c1\ud0dc\ub97c \uac19\uc774 \ud655\uc778\ud558\uc790.","\ucd08\uacfc \uc8fc\ud589\uac70\ub9ac\ub098 \ucc28\ub7c9 \uc190\uc0c1\uc5d0 \ub530\ub978 \uc815\uc0b0\uc774 \uc788\uc744 \uc218 \uc788\uc5b4\uc694.")
B.a_b=new A.hq("\uc778\uc218\ub294 \ucc28 \uac12 \uc678\uc758 \ube44\uc6a9\ub3c4 \ub354\ud574\uc694","\ucc28\ub7c9\uc744 \ub0b4 \uba85\uc758\ub85c \uac00\uc838\uc624\ub824\uba74 \uacc4\uc57d\uc5d0\uc11c \uc815\ud55c \uc778\uc218\uac00 \uc678\uc5d0 \ucde8\ub4dd\uc138\uc640 \uc774\uc804 \ube44\uc6a9 \ub4f1\uc774 \ub4e4 \uc218 \uc788\uc5b4\uc694. \uc138\uae08\uc740 \ucc28\uc885\uacfc \uc801\uc6a9 \uc694\uac74\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c0\ubbc0\ub85c \ud55c \uac00\uc9c0 \uc138\uc728\ub85c \ub2e8\uc815\ud558\uc9c0 \ub9d0\uace0 \ucd5c\uc885 \uc778\uc218 \uacac\uc801\uc744 \ud655\uc778\ud558\uc138\uc694.","\uc778\uc218\uac00\ub9cc \ubcf4\uba74 \uc548 \ub418\ub124. \uc138\uae08\uacfc \uc774\uc804 \ube44\uc6a9\uae4c\uc9c0!","\uc138\uae08\uacfc \uc774\uc804 \ube44\uc6a9\uc740 \ucc28\uc885\uacfc \uc801\uc6a9 \uc694\uac74\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc838\uc694.")
B.a_f=new A.hq("\ucd1d\ube44\uc6a9\uacfc \uc55e\uc73c\ub85c\uc758 \uacc4\ud68d\uc73c\ub85c \uacb0\uc815\ud574\uc694","\ube44\uc2b7\ud55c \uc5f0\uc2dd\xb7\uc8fc\ud589\uac70\ub9ac\xb7\uc0c1\ud0dc\uc758 \uc911\uace0\ucc28 \uc2dc\uc138\uc640 \ucd1d \uc778\uc218 \ube44\uc6a9\uc744 \ube44\uad50\ud574 \ubcf4\uc138\uc694. \uacc4\uc18d \ud0c8 \uae30\uac04\uacfc \uc608\uc0c1 \uc815\ube44\ube44\ub3c4 \uace0\ub824\ud574\uc57c \ud574\uc694. \uc2dc\uc138\uac00 \ub192\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \uc778\uc218\uac00 \ud56d\uc0c1 \uc720\ub9ac\ud55c \uac83\uc740 \uc544\ub2c8\uc5d0\uc694.","\uc55e\uc73c\ub85c \uc5bc\ub9c8\ub098 \ud0c8\uc9c0\uae4c\uc9c0 \uc0dd\uac01\ud574\uc11c \ub098\uc5d0\uac8c \ub9de\uac8c \uace0\ub974\uc790.","\ucc28\ub7c9 \uc2dc\uc138\ubfd0 \uc544\ub2c8\ub77c \uc55e\uc73c\ub85c\uc758 \uc774\uc6a9 \uacc4\ud68d\ub3c4 \uc911\uc694\ud574\uc694.")
B.a4r=s([B.a_9,B.a_g,B.a_b,B.a_f],t.ca)
B.a_o=new A.wG("end_of_term","\ub9cc\uae30 \uac00\uc774\ub4dc","\ub9cc\uae30\uc5d0 \uc778\uc218\ud560\uae4c, \ubc18\ub0a9\ud560\uae4c?","\uc815\ub2f5\uc740 \ud558\ub098\uac00 \uc544\ub2c8\uc5d0\uc694. \uacc4\uc57d \uc870\uac74\uacfc \uc55e\uc73c\ub85c \ucc28\ub97c \uc4f8 \uacc4\ud68d\uc744 \ud568\uaed8 \ubcf4\uc138\uc694.",B.a8h,B.a4r,"\uc911\ub3c4\ud574\uc9c0\uc640 \ub9cc\uae30 \ubc18\ub0a9\uc740 \ub2e4\ub978 \uc808\ucc28\uc608\uc694. \ub9cc\uae30 \uc120\ud0dd \uac00\ub2a5 \uc5ec\ubd80, \uc778\uc218 \ube44\uc6a9, \ubc18\ub0a9 \uc815\uc0b0 \uae30\uc900\uc740 \uacc4\uc57d\uc11c\uac00 \uae30\uc900\uc774\uc5d0\uc694.")
